#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main()
{
    ifstream file("example.txt"); // open the file
    string word_to_count = "hello"; // the word to count
    string line;
    int count = 0;

    while (getline(file, line)) // read the file line by line
    {
        size_t pos = 0;
        while ((pos = line.find(word_to_count, pos)) != string::npos) // count occurrences of the word in the line
        {
            count++;
            pos += word_to_count.size();
        }
    }

    cout << "The word \"" << word_to_count << "\" appears " << count << " times in the file." << endl;

    return 0;
}
