			name: 'user',
			type: 'Member',
			description: 'The member to ban',
			required: true
		}
	],

	// The actual command code
	async execute(message, args) {
		// Get the user to ban
		const user = message.mentions.users.first();

		// Make sure the user is valid
		if (!user) {
			return message.channel.send(embed);
		}

		// Get the guild where the command was executed
		const guild = message.guild;

		// Make sure the user is a member of the guild
		if (!guild.member(user)) {
			return message.channel.send('User not found.');
		}

		// Ban the user
		try {
			await user.ban(guild);

			// Send a message to the user who executed the command
			message.channel.send({
				content: `${user.user.tag} has been banned.`,
				embed: embed
			});
		} catch (err) {
